-- Two hundred and thirty-eight equipment rows from the Palladium RPG Main
-- Book "Additional Equipment" tables, p.272-274: clothing, containers, field
-- equipment, camping, lighting, writing equipment, edibles (fowl, fish,
-- fresh meat, prepared and preserved, other), feed grain, beverages and
-- miscellaneous. Extracted from page scans rendered at 300dpi.
--
-- One-off data script, run once per environment. NOT a migration - it adds
-- rows, not schema.
--
--   node scripts/d1-apply.mjs --local apps/character-creator/db/add-pf-equipment-batch.sql
--
-- Five rows fill existing palladium-fantasy STUBs in place by slug:
--   boots      -> Boots (Leather), the plain-leather reading of a bare grant
--   belt       -> Belt
--   water-skin -> Water skin, 2 pints (the smallest of the book's three)
--   rope       -> Rope (per 40 ft./12m)
--   tinder-box -> Tinder box
-- Ambiguous stubs (bedroll, purse-satchel, traveling-robe-or-cloak-with-hood,
-- and the generic sword/spear/staff/blunt-weapon/chain-weapon) are left
-- alone rather than guessed at.
--
-- Four slugs carry a -pf suffix (back-pack-pf, large-sack-pf, small-sack-pf,
-- sleeping-bag-pf) because the natural slug belongs to a RIFTS stub this
-- script must not clobber; and Glass is drinking-glass for the same reason
-- names make bad slugs.
--
-- Pricing decisions, following the isp_note/ppe_note precedent (migrations
-- 020/021: the numeric column holds the minimum, a note carries the rest):
-- - Range costs ("1-2 gold", "12-120 gold") store the low end; the
--   description says "Cost as printed: ...".
-- - Dice costs ("2D4 gold" spices and tonics, "2D6 gold" snuff/perfume/
--   chewing tobacco) store the dice minimum, noted the same way.
-- - Per-dozen / per-unit prices store the printed unit price with the unit
--   in the description ("Priced per dozen.", "Priced per 4 ft length.").
-- - Fractional costs print as "1/2 gold" (socks, cooking oil); stored 0.5 -
--   SQLite's INTEGER affinity keeps a non-integral REAL as REAL.
-- - Traps' damage ("does 1D6 damage") goes in the damage column.
-- - Two typesetting errors corrected, noted on the rows: "Shin (silk)" is
--   Shirt (Silk), "Lamp leg or roast" is Lamb.
-- - Page-level quality multipliers (fancy/tailored clothing, high-quality
--   food, excellent alcohol) are rules, not rows; not stored.
--
-- ON CONFLICT (slug) DO UPDATE, deliberately: re-running is repair, and the
-- stub fills depend on it. Pure ASCII on purpose - see PR #101's pre-flight.

ON CONFLICT (slug) DO UPDATE SET
  name = excluded.name,
  system = excluded.system,
  category = excluded.category,
  cost = excluded.cost,
  damage = excluded.damage,
  description = excluded.description,
  source_book = excluded.source_book;

-- Read the result back rather than trusting the exit code.
SELECT COUNT(*) AS pf_equipment_rows FROM gear WHERE source_book LIKE 'Palladium RPG Main Book p.27%' AND category = 'gear' AND source_book NOT LIKE '%p.270%' AND source_book NOT LIKE '%p.271%';
SELECT slug, name, cost FROM gear WHERE slug IN ('boots', 'belt', 'water-skin', 'rope', 'tinder-box');
SELECT slug, name, system FROM gear WHERE slug IN ('back-pack', 'large-sack', 'small-sack', 'sleeping-bag');
SELECT slug, cost, description FROM gear WHERE slug IN ('socks', 'spices-per-2-ounces', 'champagne', 'candle-fast-burning-45-minutes');
SELECT COUNT(*) AS remaining_pf_stubs FROM gear WHERE system = 'palladium-fantasy' AND description LIKE 'STUB%';

-- Records this run. One row per run rather than per file: every statement
-- above guards itself, so this script is safe to re-run and safe to run
-- early, and a run that correctly did nothing is still a run that happened.
-- See db/migrations/024-data-script-runs.sql.
